const j = $input.first().json;
const p =
  j.body && typeof j.body === 'object' && !Array.isArray(j.body) && j.body.photo
    ? j.body
    : j;

const b64 = p.photo?.contentBase64;
if (!b64) throw new Error('photo.contentBase64 missing');

const buf = Buffer.from(String(b64).replace(/^data:[^;]+;base64,/i, ''), 'base64');
const fileName = String(p.photo?.name || 'upload.jpg');
const mimeType = p.photo?.mimeType || 'image/jpeg';
const rawB64 = buf.toString('base64');

const prompt =
  String(p.prompt || '').trim() ||
  'Transform this portrait into a high-quality 3D anime character style, clean lighting, soft skin, expressive eyes, keep face likeness, single person, portrait framing, no text, no watermark';

const u = p.user || {};

return [
  {
    json: {
      event: p.event || 'ubu_freshie_anime_3d',
      style: p.style || '3d_anime',
      prompt,
      fileName,
      mimeType,
      imageDataUrl: `data:${mimeType};base64,${rawB64}`,
      userEmail: String(u.email || '').trim(),
      userFullname: String(u.fullname || u.username || '').trim()
    }
  }
];

const item = $input.first().json;

const model = 'google/gemini-2.5-flash-image';
const prompt =
  String(item.prompt || '').trim() ||
  'Transform this portrait into a high-quality 3D anime character style, keep face likeness, single person, portrait framing, no text, no watermark';

return [
  {
    json: {
      ...item,
      gatewayBody: {
        model,
        modalities: ['image', 'text'],
        max_tokens: 8192,
        messages: [
          {
            role: 'user',
            content: [
              { type: 'image_url', image_url: { url: item.imageDataUrl } },
              { type: 'text', text: prompt }
            ]
          }
        ],
        image_config: {
          aspect_ratio: '1:1'
        }
      }
    }
  }
];

const res = $input.first().json;
const prep = $('เตรียมรูป').first().json;

if (res?.error || res?.errorMessage) {
  const err = res.errorMessage || res.message || res.error?.message || JSON.stringify(res.error || res).slice(0, 400);
  return [{ json: { error: 'ai_gateway_http_error', message: String(err) } }];
}

function pickImageUrl(msg) {
  if (!msg) return null;
  const images = msg.images;
  if (images?.length) {
    return images[0]?.image_url?.url || images[0]?.imageUrl?.url || null;
  }
  const c = msg.content;
  if (typeof c === 'string' && /^data:image\//i.test(c.trim())) return c.trim();
  if (Array.isArray(c)) {
    for (const p of c) {
      if (p?.type === 'image_url' && p?.image_url?.url) return p.image_url.url;
      if (typeof p?.text === 'string' && /^data:image\//i.test(p.text.trim())) return p.text.trim();
    }
  }
  return null;
}

const choice = res?.choices?.[0];
const msg = choice?.message;
const url = pickImageUrl(msg);
if (!url) {
  const usage = res?.usage || {};
  const finish = choice?.finish_reason || choice?.native_finish_reason;
  let hint = res?.error?.message || res?.message || '';
  if (!hint) {
    hint = `Gemini ตอบว่าง (finish=${finish ?? 'null'}, in=${usage.prompt_tokens ?? 0}, out=${usage.completion_tokens ?? 0}) — ลอง Generate อีกครั้ง`;
  }
  return [{ json: { error: 'ai_gateway_no_images', message: 'ระบบ AI ยังไม่ส่งรูปกลับมา — กรุณากด Generate 3D อีกครั้ง' } }];
}

let imageBase64 = url;
let mimeType = 'image/png';

if (String(url).startsWith('data:')) {
  const m = String(url).match(/^data:([^;]+);base64,(.+)$/i);
  if (m) {
    mimeType = m[1];
    imageBase64 = m[2];
  }
} else if (String(url).startsWith('http')) {
  return [{ json: { error: 'http_url_unsupported', message: 'Model returned http URL — use data URL or add download node' } }];
}

return [
  {
    json: {
      imageBase64,
      mimeType,
      style: prep.style || '3d_anime'
    }
  }
];
